 out=ROOT/'validation/integrated'/sys.argv[1];out.mkdir(exist_ok=False);shutil.copyfile(__file__,out/'producer.py');assert not(ROOT/'runtime/STOP').exists();src=ROOT/'validation/integrated'/sys.argv[2]/'summary.json';s=json.loads(src.read_text());a=np.load(REPO/s['field']['path']);state=json.loads((REPO/s['state']['path']).read_text());old=json.loads((REPO/s['source']['path']).read_text());n='F0_ROOT_BACK';p=a[n+'_points_mm'];t=a[n+'_tetra'];off=int(a[n+'_offset']);u=a['u_mm'][off:off+3*len(p)].reshape(-1,3);f=a['applied_force_N'][off:off+3*len(p)].reshape(-1,3).copy();vol=abs(np.linalg.det(p[t[:,1:]]-p[t[:,0,None]]))/6;lump=np.zeros(len(p))
 for j in range(4):np.add.at(lump,t[:,j],vol/4)
 f[:,2]+=lump*float(a[n+'_rho_kg_m3'])*1e-9*9.80665;sel=abs(p[:,0]-50.5)<1e-5;row,z,center=fit(p[sel],u[sel]);uniform_z=z.copy();w=a['Root_port_weights_mm2'][sel];pp=p[sel]-center;A=np.concatenate([np.column_stack((np.eye(3),-np.array([[0,-q[2],q[1]],[q[2],0,-q[0]],[-q[1],q[0],0]]))) for q in pp]);sw=np.sqrt(np.repeat(w,3));z=np.linalg.lstsq(A*sw[:,None],u[sel].ravel()*sw,rcond=None)[0];row['weighting']='independent sqrt-area least squares';row['weighted_translation_mm']=z[:3].tolist();row['weighted_rotation_rad']=z[3:].tolist();rigid=z[:3]+np.cross(z[3:],p-center);actualwork=float(np.sum(f*u));rigidwork=float(np.sum(f*rigid));nonrigidwork=float(np.sum(f*(u-rigid)));active=np.linalg.norm(f,axis=1)>1e-12;refw=np.r_[f.sum(0),np.cross(p*.001,f).sum(0)];rootdiff=refw-np.array(state['Root_origin_wrench_N_Nm'])
