 uniformwork=float(np.sum(f*(uniform_z[:3]+np.cross(uniform_z[3:],p-center))));checks=dict(dual_work=abs(nonrigidwork)<1e-12,unweighted_control_rejected=abs(actualwork-uniformwork)>1e-12,root_traction_only_on_original_face=bool(np.all(sel[active])),root_force=np.linalg.norm(rootdiff[:3])<1e-8,root_moment=np.linalg.norm(rootdiff[3:])<1e-10,work_decomposition=abs(actualwork-rigidwork-nonrigidwork)<1e-16,shaft_command_axis_torque=abs(localmoment[1]-state['T_N']*.01125)<1e-10,front_gaps_open=all(r['minimum_gap_mm']>0 and r['reaction_sum_N']==0 for r in contact if r['label'].startswith('motor_front')))
